internal const val MAX_FRAME_BYTES = 2 * 1024 * 1024
private fun line(source: BufferedSource): String? = try {
    source.readUtf8LineStrict(MAX_FRAME_BYTES.toLong())
} catch (eof: EOFException) {
    require(source.buffer.size <= MAX_FRAME_BYTES) { "Analysis frame too large." }
    // An unterminated last line is valid at EOF. Only consume the bounded buffer.
    if (source.buffer.size == 0L) null else source.buffer.readUtf8()
}

line.startsWith("data:") -> {
    val value=line.substringAfter(':').trimStart()
    dataBytes+=value.utf8Size()+1
    require(dataBytes<=MAX_FRAME_BYTES) { "Analysis frame too large." }
    data.append(value).append('\n')
}

package com.instinctazero.android

import okhttp3.ResponseBody
import java.io.IOException

/** Enforce a byte budget before allocating a decoded response string, including
 * unknown-length/chunked responses. The caller owns and closes the response. */
internal fun ResponseBody?.boundedString(maximumBytes: Int): String {
    require(maximumBytes >= 0)
    if (this == null) return ""
    if (contentLength() > maximumBytes || source().request(maximumBytes.toLong() + 1)) {
        throw IOException("Gateway response is too large.")
    }
    return string()
}

private val uciPattern = Regex("[a-h][1-8][a-h][1-8][qrbn]?")
fun readColumns(db: SQLiteDatabase, cancellation: CancellationSignal? = null): Set<String> =
    db.rawQuery("PRAGMA table_info(nodes)", null, cancellation).use { rows ->
        buildSet { while (rows.moveToNext()) { cancellation?.throwIfCanceled(); add(rows.getString(1)) } }
    }

private fun edgeEdit(before: String, uci: String): JSONObject? {
    val key = before to uci
    // Cache absent edits too: getOrPut would rehash every miss.
    if (!edgeEdits.containsKey(key)) edgeEdits[key] = local.optJSONObject(edgeKey(before,uci))
    return edgeEdits[key]

// Preserve source order, but index local additions once instead of scanning the
// entire edit library for every visited position and every candidate move.
private val localByBefore by lazy { localNodes.groupBy { it.before } }
private val localByFen by lazy { localNodes.groupBy { it.fen } }
private val localByPath by lazy { localNodes.associateBy { it.path } }

internal class RepertoireStore(context: Context, private val openDatabase: (File) -> SQLiteDatabase = {
