private val whitespace = Regex("\\s+")
private val uci = Regex("[a-h][1-8][a-h][1-8][qrbn]?")
fun position(fen: String): String = fen.trim().split(whitespace).take(4).joinToString(" ")

/** A fully cached request needs no connection. A miss shares one connection, closed
 * even on cancellation; no handle survives an atomic source replacement. */
private fun <T> withLazySource(block: (() -> SQLiteDatabase?) -> T): T {
    val database = lazy(LazyThreadSafetyMode.NONE) { source() }
    try { return block { database.value } }
    finally { if (database.isInitialized()) database.value?.close() }
}
private fun positionBook(db: SQLiteDatabase?, rep: String, cancellation: CancellationSignal?): RepertoirePositionBook {
    val columns = if (db == null) emptySet() else sourceColumns
        ?: RepertoirePositionBook.readColumns(db, cancellation).also { sourceColumns = it }
    return RepertoirePositionBook(db, rep, overrides(rep), localRoot(rep), cancellation, activityCache, columns)
}

@Test fun unterminatedOversizedLinesAreBoundedEvenOutsideDataFields() {
    for (prefix in listOf("data: ", "event: ", ": ")) {
        val limit = AnalysisStreamReader.MAX_FRAME_BYTES
        var bytes = 0L
        val stream = object : Source {
            override fun read(sink: Buffer, byteCount: Long): Long {
                val count = minOf(byteCount, 64L * 1024 * 1024 - bytes).toInt()
                if (count == 0) return -1
                val data = ByteArray(count) { 'a'.code.toByte() }
                if (bytes == 0L) prefix.toByteArray().copyInto(data)
                sink.write(data); bytes += count; return count.toLong()
            }
            override fun timeout() = Timeout.NONE
            override fun close() {}
        }.buffer()
        stream.use {
            assertThrows(IllegalArgumentException::class.java) {
                AnalysisStreamReader.read(it, { true }) { fail("Oversized frame must not be emitted") }
            }
        }
        assertTrue("Unterminated $prefix line must not read to EOF", bytes <= limit + 8192)
    }
}
@Test fun crlfAndMultilineJsonPreserveTerminalFrames() {
    val body = Buffer().writeUtf8("event: done\r\ndata: {\r\ndata: \"cancelled\":false}\r\n\r\n")
    var frames = 0
    assertTrue(AnalysisStreamReader.read(body, { true }) {
        frames++; assertFalse(it.getJSONObject("data").getBoolean("cancelled"))
    })
    assertEquals(1, frames)
}
@Test fun manySmallDataLinesCannotExceedTheFrameBudget() {
    val body = Buffer()
    repeat(2049) { body.writeUtf8("data: " + "a".repeat(1024) + "\n") }
    assertThrows(IllegalArgumentException::class.java) { AnalysisStreamReader.read(body, { true }) {} }
}

package com.instinctazero.android

import okhttp3.MediaType.Companion.toMediaType
import okhttp3.ResponseBody
import okhttp3.ResponseBody.Companion.toResponseBody
import okio.Buffer
import okio.BufferedSource
import okio.Source
import okio.Timeout
import okio.buffer
import org.junit.Assert.*
import org.junit.Test
import java.io.IOException

class BoundedResponseBodyTest {
    private class CountingBody(private val length: Long, private val reportedLength: Long = -1) : ResponseBody() {
        var bytesRead = 0L
        var closed = false
        private val buffered = object : Source {
            override fun read(sink: Buffer, byteCount: Long): Long {
                val count = minOf(byteCount, length - bytesRead).toInt()
                if (count == 0) return -1
                sink.write(ByteArray(count) { 'a'.code.toByte() }); bytesRead += count
                return count.toLong()
            }
            override fun timeout() = Timeout.NONE
            override fun close() { closed = true }
        }.buffer()
        override fun contentType() = null
        override fun contentLength() = reportedLength
        override fun source(): BufferedSource = buffered
    }

    @Test fun oversizedKnownLengthIsRejectedWithoutReading() {
        val body = CountingBody(1_000_000, 1_000_000)
        body.use { assertThrows(IOException::class.java) { it.boundedString(1024) } }
        assertEquals(0L, body.bytesRead); assertTrue(body.closed)
    }
    @Test fun unknownAndMisreportedLengthsStopWithinOneBufferSegmentOfTheBudget() {
        for (reported in listOf(-1L, 10L)) {
            val body = CountingBody(1_000_000_000, reported)
            body.use { assertThrows(IOException::class.java) { it.boundedString(1024) } }
            assertTrue(body.bytesRead <= 1024 + 8192); assertTrue(body.closed)
        }
    }
    @Test fun boundariesEmptyResponsesAndUnicodeAreMeasuredInBytes() {
        assertEquals("", (null as ResponseBody?).boundedString(0))
        assertEquals("", "".toResponseBody().boundedString(0))
        assertEquals("éé", "éé".toResponseBody().boundedString(4))
        "éé".toResponseBody().use { assertThrows(IOException::class.java) { it.boundedString(3) } }
        assertEquals("a".repeat(1024), CountingBody(1024).boundedString(1024))
    }
    @Test fun okhttpCharsetAndBomDecodingArePreserved() {
        val latin1 = byteArrayOf(0xe9.toByte()).toResponseBody("text/plain; charset=iso-8859-1".toMediaType())
        assertEquals("é", latin1.boundedString(1))
        val bom = Buffer().writeHex("fffe6100").readByteArray().toResponseBody("text/plain; charset=utf-8".toMediaType())
        assertEquals("a", bom.boundedString(4))
    }
}

